# ---------------------------------------------------------------------------
# codex refresh CAS (remote/api_keys.rotate_codex_bundle — ADR 0015 D-d, issue 06)
# Real store + real flock on GRID_HOME=tmp_path; the vendor is always MockTransport.
# ---------------------------------------------------------------------------

def _raw_codex_entry():
    """The codex TOML table as written — for asserting journal presence, which
    `load_codex_bundle` deliberately does not surface."""
    from remote import credentials

    return credentials.load_toml(paths.api_keys_file()).get("codex") or {}


def test_codex_rotate_journals_before_the_exchange_and_persist_clears_it(monkeypatch, tmp_path):
    """ADR 0015 D-d's crash-window discipline: the in-flight exchange is journaled BEFORE the
    vendor call (a kill after the vendor rotates but before we persist must be detectable), and
    the new bundle is persisted the moment it returns — a wholesale replace, so the journal
    field vanishes with no cleanup code to forget."""
    from remote import api_keys

    monkeypatch.setenv("GRID_HOME", str(tmp_path))
    api_keys.store_codex_bundle(_codex_bundle())
    new_access = _codex_jwt({"chatgpt_account_id": "acct-1"}, exp=2_000_000_000)

    def vendor(request):
        assert "refresh_pending_since" in _raw_codex_entry()  # journaled before the network call
        return httpx.Response(200, json={"access_token": new_access, "refresh_token": "rt-2"})

    _mock_vendor(monkeypatch, vendor)

    fresh = api_keys.rotate_codex_bundle("tok-access")

    assert fresh.access_token == new_access and fresh.refresh_token == "rt-2"
    assert api_keys.load_codex_bundle() == fresh  # persisted immediately, not held in memory
    assert "refresh_pending_since" not in _raw_codex_entry()  # the wholesale replace cleared it


def test_codex_rotate_adopts_a_fresher_store_without_spending(monkeypatch, tmp_path):
    """The loser's half of the CAS: the store already holds a token fresher than the one that just
    401ed, so another process rotated first — adopt it and spend NOTHING (the refresh token is
    single-use; a second exchange would revoke the seat)."""
    from remote import api_keys, codex_oauth

    monkeypatch.setenv("GRID_HOME", str(tmp_path))
    winner = codex_oauth.CodexBundle(
        access_token="tok-access-2", refresh_token="tok-refresh-2", account_id="acct-1",
        plan_type="free", last_refresh=1_700_000_000,
    )
    api_keys.store_codex_bundle(winner)
    _mock_vendor(monkeypatch, lambda request: pytest.fail("the loser must never reach the vendor"))

    adopted = api_keys.rotate_codex_bundle("tok-access-STALE")

    assert adopted == winner
    assert "refresh_pending_since" not in _raw_codex_entry()  # adopt writes nothing


def test_codex_rotate_two_concurrent_refreshers_spend_one_exchange(monkeypatch, tmp_path):
    """AC 4, on the REAL file lock: each `file_lock` acquisition opens its own fd, so two threads
    genuinely contend like two processes do. The winner journals + exchanges + persists under the
    lock; the loser blocks, re-reads, sees the fresher token, and adopts — exactly ONE vendor
    exchange for N racers."""
    from remote import api_keys

    monkeypatch.setenv("GRID_HOME", str(tmp_path))
    api_keys.store_codex_bundle(_codex_bundle())
    new_access = _codex_jwt({"chatgpt_account_id": "acct-1"}, exp=2_000_000_000)
    exchanges = []

    def vendor(request):
        exchanges.append(1)
        time.sleep(0.2)  # hold the winner in the exchange so the loser really blocks on the flock
        return httpx.Response(200, json={"access_token": new_access, "refresh_token": "rt-2"})

    _mock_vendor(monkeypatch, vendor)
    results, errors = [], []

    def racer():
        try:
            results.append(api_keys.rotate_codex_bundle("tok-access"))
        except Exception as exc:  # surfaced below — a hang would be worse than a raise
            errors.append(exc)

    threads = [threading.Thread(target=racer, daemon=True) for _ in range(2)]
    for t in threads:
        t.start()
    for t in threads:
        t.join(10)

    assert errors == []
    assert len(exchanges) == 1  # one vendor exchange; the loser adopted
    assert [r.access_token for r in results] == [new_access, new_access]
    assert api_keys.load_codex_bundle().access_token == new_access


def test_codex_rotate_reports_an_interrupted_rotation_when_a_journal_was_left_behind(monkeypatch, tmp_path):
    """AC 6: a kill between the journal write and the persist leaves `refresh_pending_since` on
    disk. The NEXT attempt that the vendor refuses must say so — `interrupted=True` is what turns
    "the vendor said no" into "a previous rotation was lost; sign in again" instead of a silent
    zombie. The journal stays (only a persisted bundle resolves the doubt) and the stored bundle
    is untouched."""
    from remote import api_keys, credentials

    monkeypatch.setenv("GRID_HOME", str(tmp_path))
    api_keys.store_codex_bundle(_codex_bundle())
    # Simulate the kill: a journal from a dead attempt, planted exactly as the CAS writes it.
    data = credentials.load_toml(paths.api_keys_file())
    credentials.atomic_write_toml(
        paths.api_keys_file(),
        {**data, "codex": {**data["codex"], "refresh_pending_since": 1_700_000_000}},
    )
    _mock_vendor(monkeypatch, lambda request: httpx.Response(400, json={"error": "invalid_grant"}))

    with pytest.raises(api_keys.CodexRotationRefused) as caught:
        api_keys.rotate_codex_bundle("tok-access")

    assert caught.value.interrupted is True
    assert caught.value.status_code == 400
    assert "refresh_pending_since" in _raw_codex_entry()  # still unresolved — keeps re-diagnosing
    assert api_keys.load_codex_bundle() == _codex_bundle()  # the stored bundle is untouched


def test_codex_rotate_refusal_without_a_journal_is_not_interrupted(monkeypatch, tmp_path):
    """The plain dead-seat case (revoked, signed out elsewhere): the vendor refuses but no prior
    exchange died mid-flight — `interrupted` must be False, or every refusal would carry the
    scarier lost-rotation diagnosis and the operator could not tell the two apart.

    And it must STAY False on every subsequent refusal: a definitive refusal is a completed
    attempt, so it withdraws its OWN journal — left behind, attempt 1's pre-call journal write
    would become attempt 2's "a prior exchange died" evidence, and a stably-dead seat would be
    misdiagnosed as a lost rotation from the second refusal onward, forever (silent-failure
    review). `interrupted` means exactly "an exchange died between the vendor call and the
    persist" — nothing here died."""
    from remote import api_keys

    monkeypatch.setenv("GRID_HOME", str(tmp_path))
    api_keys.store_codex_bundle(_codex_bundle())
    _mock_vendor(monkeypatch, lambda request: httpx.Response(401, json={}))

    with pytest.raises(api_keys.CodexRotationRefused) as caught:
        api_keys.rotate_codex_bundle("tok-access")
    assert caught.value.interrupted is False
    assert "refresh_pending_since" not in _raw_codex_entry()  # a completed attempt cleans up

    with pytest.raises(api_keys.CodexRotationRefused) as caught:
        api_keys.rotate_codex_bundle("tok-access")  # the same dead seat, one cooldown later
    assert caught.value.interrupted is False  # still a plain refusal — not self-poisoned


def test_codex_journal_is_cleared_by_any_persisted_bundle_and_never_affects_loading(monkeypatch, tmp_path):
    """The journal's whole lifecycle rides the wholesale replace: a successful rotation clears it
    (pinned in the tracer test), a fresh sign-in (`store_codex_bundle`) clears it, and
    `load_codex_bundle` never even sees it — a journaled entry still loads as a valid bundle, so
    a leftover journal can never lock an operator out of their own seat."""
    from remote import api_keys, credentials

    monkeypatch.setenv("GRID_HOME", str(tmp_path))
    api_keys.store_codex_bundle(_codex_bundle())
    data = credentials.load_toml(paths.api_keys_file())
    credentials.atomic_write_toml(
        paths.api_keys_file(),
        {**data, "codex": {**data["codex"], "refresh_pending_since": 1_700_000_000}},
    )

    assert api_keys.load_codex_bundle() == _codex_bundle()  # journaled entry loads fine

    api_keys.store_codex_bundle(_codex_bundle(plan_type="plus"))  # the re-sign-in path

    assert "refresh_pending_since" not in _raw_codex_entry()  # replace=True dropped it
    assert api_keys.load_codex_bundle().plan_type == "plus"


def test_codex_rotate_clears_its_own_journal_when_the_request_never_left(monkeypatch, tmp_path):
    """A connect failure means the exchange provably never left this machine — nothing was spent,
    so OUR journal is withdrawn before re-raising. Left behind, it would sharpen a WRONG
    "rotation was lost" diagnosis out of an ordinary offline blip. An AMBIGUOUS failure
    (`ReadTimeout` — the grant may have reached the vendor) keeps the journal, truthfully."""
    from remote import api_keys, codex_oauth

    monkeypatch.setenv("GRID_HOME", str(tmp_path))
    api_keys.store_codex_bundle(_codex_bundle())

    def connect_error(request):
        raise httpx.ConnectError("offline", request=request)

    _mock_vendor(monkeypatch, connect_error)
    with pytest.raises(codex_oauth.RefreshUnavailable):
        api_keys.rotate_codex_bundle("tok-access")
    assert "refresh_pending_since" not in _raw_codex_entry()  # withdrawn — nothing was spent

    def read_timeout(request):
        raise httpx.ReadTimeout("mid-flight", request=request)

    _mock_vendor(monkeypatch, read_timeout)
    with pytest.raises(codex_oauth.RefreshUnavailable):
        api_keys.rotate_codex_bundle("tok-access")
    assert "refresh_pending_since" in _raw_codex_entry()  # ambiguous — the doubt is real, keep it


def test_codex_rotate_never_withdraws_a_journal_it_did_not_write(monkeypatch, tmp_path):
    """Withdrawal is scoped to the attempt's OWN journal: a journal left by an EARLIER crash is
    someone's unresolved doubt, and neither a connect failure (spent nothing, resolved nothing)
    nor a clean refusal may erase it — that would downgrade the next refusal's diagnosis from
    "a rotation was lost" to a plain revocation (python review). Only a persisted bundle — a
    rotation or a re-sign-in — resolves it."""
    from remote import api_keys, codex_oauth, credentials

    monkeypatch.setenv("GRID_HOME", str(tmp_path))
    api_keys.store_codex_bundle(_codex_bundle())
    data = credentials.load_toml(paths.api_keys_file())
    credentials.atomic_write_toml(
        paths.api_keys_file(),
        {**data, "codex": {**data["codex"], "refresh_pending_since": 1_700_000_000}},
    )

    def connect_error(request):
        raise httpx.ConnectError("offline", request=request)

    _mock_vendor(monkeypatch, connect_error)
    with pytest.raises(codex_oauth.RefreshUnavailable):
        api_keys.rotate_codex_bundle("tok-access")
    assert "refresh_pending_since" in _raw_codex_entry()  # the earlier crash's doubt survives

    _mock_vendor(monkeypatch, lambda request: httpx.Response(400, json={"error": "invalid_grant"}))
    with pytest.raises(api_keys.CodexRotationRefused) as caught:
        api_keys.rotate_codex_bundle("tok-access")
    assert caught.value.interrupted is True  # the crash's diagnosis, intact through the blip
    assert "refresh_pending_since" in _raw_codex_entry()  # and it keeps resurfacing


def test_codex_rotate_guards_the_empty_store_and_the_shutdown_race(monkeypatch, tmp_path):
    """Two refusals that must spend NOTHING: a store with no seat (signed out mid-serve) raises
    `CodexNotSignedIn`; a shutdown that wins the race to the lock raises `RotationAbandoned` with
    no journal written — the drain invariant is 'flag unset ⇒ nothing was spent AND nothing will
    be', and a journal written after stop would break its second half."""
    from remote import api_keys

    monkeypatch.setenv("GRID_HOME", str(tmp_path))
    _mock_vendor(monkeypatch, lambda request: pytest.fail("neither guard may reach the vendor"))

    with pytest.raises(api_keys.CodexNotSignedIn):
        api_keys.rotate_codex_bundle("tok-access")  # empty store

    api_keys.store_codex_bundle(_codex_bundle())
    stopping = threading.Event()
    stopping.set()
    flag = threading.Event()

    with pytest.raises(api_keys.RotationAbandoned):
        api_keys.rotate_codex_bundle("tok-access", exchange_in_flight=flag, abandon=stopping)

    assert not flag.is_set()  # cleared in the finally, abandon path included
    assert "refresh_pending_since" not in _raw_codex_entry()  # no journal after stop, ever


# ---------------------------------------------------------------------------
# Remote serve loop (remote/serve.py)
# ---------------------------------------------------------------------------

def _mock_serve_engine(monkeypatch, handler, _real=httpx.Client):
    """Serve the local engine the serve loop forwards to, via httpx.MockTransport."""
    monkeypatch.setattr(
        httpx, "Client",
        lambda *a, **k: _real(*a, **{**k, "transport": httpx.MockTransport(handler)}),
    )


def _serve_state(monkeypatch, tmp_path, **overrides):
    from remote import serve
    from shared.system import host

    monkeypatch.setenv("GRID_HOME", str(tmp_path))
    # Pin the heartbeat's platform tag so load-shape assertions are deterministic across runner OSes.
    monkeypatch.setattr(host, "platform_kind", lambda: "linux")
    kwargs = dict(
        signaling_url="https://relay.example", node_id="node-1", network_id="n1",
        llm_url="http://127.0.0.1:8081/v1", access_token="AT", refresh_token="RT",
        models=["m"], capabilities={"schema_version": 1, "models": {}},
        meta={"name": "e1", "engine": "llama.cpp"}, pricing={}, max_concurrency=1,
    )
    kwargs.update(overrides)
    return serve._ServeState(**kwargs)


def test_serve_loop_runs_one_poll_worker_per_slot(monkeypatch, tmp_path):
    """Each concurrency slot gets its own poll worker, so up to max_concurrency jobs run at once."""
    from remote import serve

    calls: list[str] = []

    def fake_poll(state):
        calls.append(threading.current_thread().name)
        state.stop.set()  # release the main-thread waiter so _serve_loop returns

    monkeypatch.setattr(serve, "_poll_loop", fake_poll)
    monkeypatch.setattr(serve, "_heartbeat_loop", lambda state: None)
    state = _serve_state(monkeypatch, tmp_path, max_concurrency=4)

    serve._serve_loop(state)

    assert len(calls) == 4


def test_serve_loop_single_worker_by_default(monkeypatch, tmp_path):
    """Default max_concurrency=1 runs exactly one poll worker — the pre-fix behavior, unchanged."""
    from remote import serve

    calls: list[str] = []

    def fake_poll(state):
        calls.append(threading.current_thread().name)
        state.stop.set()

    monkeypatch.setattr(serve, "_poll_loop", fake_poll)
    monkeypatch.setattr(serve, "_heartbeat_loop", lambda state: None)
    state = _serve_state(monkeypatch, tmp_path, max_concurrency=1)

    serve._serve_loop(state)

    assert len(calls) == 1


def test_serve_loop_starts_heartbeat_once(monkeypatch, tmp_path):
    """One heartbeat thread regardless of how many poll workers run."""
    from remote import serve

    heartbeats: list[str] = []
    monkeypatch.setattr(serve, "_poll_loop", lambda state: state.stop.set())
    monkeypatch.setattr(serve, "_heartbeat_loop", lambda state: heartbeats.append("hb"))
    state = _serve_state(monkeypatch, tmp_path, max_concurrency=3)

    serve._serve_loop(state)

    assert heartbeats == ["hb"]


def test_serve_loop_teardown_bounded_by_drain_timeout(monkeypatch, tmp_path, capsys):
    """Shutdown is bounded by one shared drain deadline, not summed per parked worker: workers stuck
    in a long-poll must not serialize teardown (state.stop can't wake a blocking relay.poll)."""
    from remote import serve

    monkeypatch.setattr(serve, "_DRAIN_TIMEOUT", 0.2)
    parked = threading.Event()  # never set during drain → workers stay "in a long-poll"

    def stuck_poll(state):
        state.stop.set()   # trigger shutdown (release the main-thread waiter)
        parked.wait(30)    # then block, ignoring state.stop, like a real relay.poll

    monkeypatch.setattr(serve, "_poll_loop", stuck_poll)
    monkeypatch.setattr(serve, "_heartbeat_loop", lambda state: parked.wait(30))
    state = _serve_state(monkeypatch, tmp_path, max_concurrency=8)

    start = time.monotonic()
    try:
        serve._serve_loop(state)
        elapsed = time.monotonic() - start
    finally:
        parked.set()  # release the daemon workers so they don't linger across the suite

    # One shared 0.2s deadline → ~0.2s total; a per-worker join would be ~8 × 0.2 = 1.6s.
    assert elapsed < 1.0
    err = capsys.readouterr().err
    # Workers abandoned at the deadline are logged, not dropped silently. They were parked in a
    # long-poll holding no job, so the line says exactly that — the consumer-facing "no terminal
    # response" warning belongs to unfinished JOBS and would be a false alarm here.
    assert "8 poll worker(s) abandoned while parked" in err
    assert "may see no terminal response" not in err
    # So is the heartbeat, which is joined BEFORE the reload thread against the same deadline — so a
    # heartbeat that overruns (e.g. a slow engine-health sweep) is also what ate the reload thread's
    # turn. Without this line an operator sees the consequence and never the cause.
    assert "Heartbeat thread still running" in err


def test_serve_state_inflight_counter_is_thread_safe(monkeypatch, tmp_path):
    """enter/exit_inference must be atomic — the N poll workers now hit the counter concurrently."""
    from shared.system import gpu

    monkeypatch.setattr(gpu, "load_snapshot", lambda timeout=3.0: {})  # no-GPU box: load is just active_tasks + platform
    state = _serve_state(monkeypatch, tmp_path, max_concurrency=8)

    def hammer():
        for _ in range(1000):
            state.enter_inference()
            state.exit_inference()

    threads = [threading.Thread(target=hammer) for _ in range(8)]
    for thread in threads:
        thread.start()
    for thread in threads:
        thread.join()

    assert state.load() == {"active_tasks": 0, "platform": "linux"}


def test_serve_loop_worker_death_stops_engine(monkeypatch, tmp_path):
    """A poll worker dying from an unexpected fault stops the whole engine (sets stop) instead of
    silently vanishing and stranding the node at reduced/zero capacity."""
    from remote import serve

    def boom(state):
        raise RuntimeError("relay handed us garbage")

    monkeypatch.setattr(serve, "_poll_loop", boom)
    monkeypatch.setattr(serve, "_heartbeat_loop", lambda state: state.stop.wait(60))
    state = _serve_state(monkeypatch, tmp_path, max_concurrency=3)

    serve._serve_loop(state)  # returns only because a dead worker set state.stop

    assert state.stop.is_set()


def test_serve_loop_starts_no_task_worker_by_default(monkeypatch, tmp_path):
    """Task serving is opt-in. Without `GRID_TASKS` a provider behaves exactly as it did before this
    feature existed — no extra thread, no extra relay traffic, no subscription spent."""
    from remote import serve, tasks

    monkeypatch.delenv("GRID_TASKS", raising=False)
    monkeypatch.setattr(tasks, "task_loop", lambda state: pytest.fail("task loop must not run"))
    monkeypatch.setattr(serve, "_poll_loop", lambda state: state.stop.set())
    monkeypatch.setattr(serve, "_heartbeat_loop", lambda state: None)
    state = _serve_state(monkeypatch, tmp_path)

    serve._serve_loop(state)

    assert not any(t.name.startswith("task-worker") for t in threading.enumerate())


def test_serve_loop_starts_one_task_worker_when_enabled(monkeypatch, tmp_path):
    from remote import serve, tasks

    monkeypatch.setenv("GRID_TASKS", "1")
    monkeypatch.delenv("GRID_MAX_TASKS", raising=False)
    names: list[str] = []
    started = threading.Event()

    def fake_task_loop(state):
        names.append(threading.current_thread().name)
        started.set()
        state.tasks_stop.wait(30)

    monkeypatch.setattr(tasks, "task_loop", fake_task_loop)
    monkeypatch.setattr(serve, "_poll_loop", lambda state: (started.wait(5), state.stop.set()))
    monkeypatch.setattr(serve, "_heartbeat_loop", lambda state: None)
    state = _serve_state(monkeypatch, tmp_path)

    serve._serve_loop(state)

    # One by default — turning task serving on may not also change how much of the operator's
    # subscription it spends. `GRID_MAX_TASKS` is the only thing that does.
    assert names == ["task-worker-1"]
    assert state.tasks_stop.is_set()  # teardown retires it, or the thread outlives the engine


# --- issue 09: how many tasks at once -------------------------------------------------------------


def _count_task_workers(monkeypatch, tmp_path):
    """Start the task workers with the loop stubbed out, and report the thread names they ran under."""
    from remote import serve, tasks

    monkeypatch.setenv("GRID_TASKS", "1")
    names: list[str] = []
    lock = threading.Lock()

    def fake_task_loop(state):
        with lock:
            names.append(threading.current_thread().name)

    monkeypatch.setattr(tasks, "task_loop", fake_task_loop)
    state = _serve_state(monkeypatch, tmp_path)

    threads = serve._start_task_worker(state)
    for thread in threads:
        thread.join(timeout=5)
    return names, state


def test_a_provider_runs_as_many_tasks_at_once_as_it_was_configured_to(monkeypatch, tmp_path):
    """The per-provider ceiling ADR 0032 calls for: configured by the operator who owns the
    subscription, never benchmarked. It binds alongside the subscription's own signal — whichever
    runs out first is the one that stops this provider claiming."""
    monkeypatch.setenv("GRID_MAX_TASKS", "3")

    names, _state = _count_task_workers(monkeypatch, tmp_path)

    assert sorted(names) == ["task-worker-1", "task-worker-2", "task-worker-3"]


@pytest.mark.parametrize("value", ["", "0", "-2", "lots", "1.5", "1e3000"])
def test_a_misconfigured_task_ceiling_falls_back_instead_of_retiring_task_serving(
        monkeypatch, tmp_path, capsys, value):
    """Same rule as `tasks.task_timeout()`: a provider that refused to serve tasks because an
    operator typed `three` would take task serving down for the life of the process, which is a far
    worse answer than running with the default and saying so."""
    monkeypatch.setenv("GRID_MAX_TASKS", value)

    names, state = _count_task_workers(monkeypatch, tmp_path)

    assert names == ["task-worker-1"]
    assert not state.tasks_stop.is_set()
    if value:
        assert "GRID_MAX_TASKS" in capsys.readouterr().err


def test_one_worker_that_cannot_start_does_not_cost_the_others(monkeypatch, tmp_path, capsys):
    """`RuntimeError: can't start new thread` under exhaustion is the reason there is no upper clamp
    on the count: the operator's number is honoured, and the machine's own limit is discovered rather
    than guessed at. Discovering it must leave the workers that DID start running."""
    from remote import serve, tasks

    monkeypatch.setenv("GRID_TASKS", "1")
    monkeypatch.setenv("GRID_MAX_TASKS", "3")
    real_thread = threading.Thread
    attempts = []

    def flaky_thread(*args, **kwargs):
        attempts.append(kwargs.get("name"))
        if len(attempts) == 2:
            raise RuntimeError("can't start new thread")
        return real_thread(*args, **kwargs)

    monkeypatch.setattr(tasks, "task_loop", lambda state: None)
    monkeypatch.setattr(serve.threading, "Thread", flaky_thread)
    state = _serve_state(monkeypatch, tmp_path)

    threads = serve._start_task_worker(state)

    assert len(threads) == 2                     # the third and first started; the second did not
    assert not state.tasks_stop.is_set()         # task serving is still on
    assert "can't start new thread" in capsys.readouterr().err


def test_task_serving_retires_only_when_no_worker_could_start(monkeypatch, tmp_path, capsys):
    """Nothing is claiming, so saying so is the honest record — the same retirement a relay with no
    tasks plane produces, and it still leaves inference alone."""
    from remote import serve, tasks

    monkeypatch.setenv("GRID_TASKS", "1")
    monkeypatch.setenv("GRID_MAX_TASKS", "2")
    monkeypatch.setattr(tasks, "task_loop", lambda state: None)
    monkeypatch.setattr(serve.threading, "Thread", _raise(RuntimeError("can't start new thread")))
    state = _serve_state(monkeypatch, tmp_path)

    assert serve._start_task_worker(state) == []
    assert state.tasks_stop.is_set()
    assert not state.stop.is_set()


def test_a_task_capacity_block_changes_nothing_the_relay_ROUTES_ON(monkeypatch, tmp_path):
    """Task capacity is client-side and stops at this process's edge. It deliberately adds nothing to
    the heartbeat: the relay routes inference on `load`, and a provider out of TASK headroom is still
    a perfectly good provider of inference. Publishing it would also make it a cross-repo lockstep
    value, and there is nothing on the other side that needs one — a provider that stops claiming is
    simply not handed a task."""
    from shared.system import gpu

    from remote import task_capacity

    monkeypatch.setattr(gpu, "load_snapshot", lambda timeout=3.0: {})
    state = _serve_state(monkeypatch, tmp_path)
    before = state.load()

    gate = task_capacity.TaskCapacity()
    gate.observe({"status": "rejected", "rateLimitType": "five_hour",
                  "resetsAt": int(time.time() + 3600)})

    assert gate.pause_seconds() > 0.0        # this provider really is out of task headroom
    assert state.load() == before            # ...and the inference plane's wire payload is untouched


def test_a_provider_saturated_with_inference_can_still_take_a_task(monkeypatch):
    """The other direction of the same independence. The task loop reads nothing from the inference
    counters — a box with every poll slot busy is a box whose Claude subscription is untouched, and
    the two ceilings are not the same ceiling (ADR 0032)."""
    tasks, state, fake_claim = _task_loop_state([{"task_id": "T1", "prompt": "x"}])
    state.max_concurrency = 4
    state.enter_inference = state.exit_inference = lambda: None
    reported = []

    monkeypatch.setattr(tasks, "claim_once", fake_claim)
    monkeypatch.setattr(tasks, "run_task", lambda job, *_a, **_k: tasks.TaskOutcome("completed", "", None))
    monkeypatch.setattr(tasks, "report_once", lambda _s, tid, **kw: reported.append(tid))

    tasks.task_loop(state, capacity=_scripted_gate([], []))

    assert reported == ["T1"]


def test_serve_loop_task_worker_death_does_not_stop_the_engine(monkeypatch, tmp_path):
    """The deliberate counterpart to `test_serve_loop_worker_death_stops_engine`.

    A dead POLL worker strands advertised inference capacity, so it stops the engine. A dead TASK
    worker strands nothing that was advertised — the node keeps serving inference — so it must NOT.
    This is the acceptance criterion "stopping one leaves the other serving", in the direction that
    `_supervise` would silently get wrong.
    """
    from remote import serve, tasks

    monkeypatch.setenv("GRID_TASKS", "1")
    polls = threading.Event()

    def boom(state):
        raise RuntimeError("task plane exploded")

    def poll(state):
        polls.wait(5)          # keep serving inference after the task worker has died
        state.stop.set()

    monkeypatch.setattr(tasks, "task_loop", boom)
    monkeypatch.setattr(serve, "_poll_loop", poll)
    monkeypatch.setattr(serve, "_heartbeat_loop", lambda state: None)
    state = _serve_state(monkeypatch, tmp_path)

    threading.Timer(0.3, polls.set).start()
    serve._serve_loop(state)

    # The engine stopped because the POLL worker said so, not because the task worker died.
    assert polls.is_set()


def test_task_worker_that_fails_to_START_does_not_take_the_engine_down(monkeypatch, tmp_path, capsys):
    """The one call in this feature that runs on the MAIN thread, outside every other guard.

    `_start_task_worker` is invoked before `_serve_loop`'s own try/finally, so an exception there —
    an import fault in `remote/tasks.py`, `RuntimeError: can't start new thread` under exhaustion —
    would propagate out of `_serve_loop` to the top-level handler, unregister the node and kill the
    process. A task-plane STARTUP fault must be as survivable as a task-plane runtime fault.
    """
    from remote import serve

    monkeypatch.setenv("GRID_TASKS", "1")
    monkeypatch.setattr(serve, "_task_serving_enabled", _raise(RuntimeError("cannot start thread")))
    monkeypatch.setattr(serve, "_poll_loop", lambda state: state.stop.set())
    monkeypatch.setattr(serve, "_heartbeat_loop", lambda state: None)
    state = _serve_state(monkeypatch, tmp_path)

    serve._serve_loop(state)  # must return normally, not raise

    assert "cannot start thread" in capsys.readouterr().err  # loud, but not fatal


def test_task_worker_death_is_logged_and_retires_task_serving(monkeypatch, tmp_path, capsys):
    """`task_loop` self-guards, so reaching here means a fault OUTSIDE its guard. The thread must
    not simply vanish: an unguarded raise would strand task serving silently for the life of the
    process — the exact failure `_supervise` exists to prevent, minus the engine teardown."""
    from remote import serve, tasks

    monkeypatch.setenv("GRID_TASKS", "1")
    monkeypatch.setattr(tasks, "task_loop", _raise(RuntimeError("task plane exploded")))
    state = _serve_state(monkeypatch, tmp_path)

    threads = serve._start_task_worker(state)
    for thread in threads:
        thread.join(timeout=5)

    err = capsys.readouterr().err
    assert "task-worker" in err and "task plane exploded" in err
    assert state.tasks_stop.is_set()   # task serving is honestly marked as retired
    assert not state.stop.is_set()     # ...and inference is untouched


def test_serve_loop_task_stop_does_not_stop_inference(monkeypatch, tmp_path):
    """Retiring the task loop (a relay with no tasks plane, a bad task credential) leaves the poll
    workers serving — the other direction of the same independence."""
    from remote import serve, tasks

    monkeypatch.setenv("GRID_TASKS", "1")
    served: list[int] = []
    retired = threading.Event()

    def fake_task_loop(state):
        state.tasks_stop.set()   # retire immediately, as the 404 path does
        retired.set()

    def poll(state):
        retired.wait(5)
        served.append(1)         # inference still dispatching after the task loop retired
        state.stop.set()

    monkeypatch.setattr(tasks, "task_loop", fake_task_loop)
    monkeypatch.setattr(serve, "_poll_loop", poll)
    monkeypatch.setattr(serve, "_heartbeat_loop", lambda state: None)
    state = _serve_state(monkeypatch, tmp_path)

    serve._serve_loop(state)

    # Inference dispatched AFTER the task loop retired — that is the whole claim. (`state.stop` is
    # set here by the poll worker's own exit, so asserting on it would prove nothing either way.)
    assert served == [1]
    assert state.tasks_stop.is_set()


def test_serve_state_exposes_an_independent_task_stop_event(monkeypatch, tmp_path):
    """Two events, not one: `stop` tears the engine down, `tasks_stop` retires task serving alone."""
    state = _serve_state(monkeypatch, tmp_path)

    state.tasks_stop.set()

    assert not state.stop.is_set()


def test_a_task_and_an_inference_job_are_in_flight_at_the_same_moment(monkeypatch, tmp_path):
    """Issue 03's last criterion, asserted on the two planes being busy AT ONCE.

    Its three siblings each RETIRE one plane and watch the other keep going — task loop retires and
    inference still dispatches, inference saturates and a task is still claimable, a capacity pause
    leaves inference untouched. Every one of them is a statement about a plane that has STOPPED, and
    all three would still pass if the two planes ran strictly one after the other. What ADR 0032
    actually claims is concurrency: a provider serves inference *while* a task is running, for the
    hour that task takes.

    The failure this closes is not hypothetical — issue 01's review found `_start_task_worker`
    running unguarded on the main thread, ahead of `_serve_loop`'s try/finally. A task loop that
    blocked there would starve inference completely, and nothing in the suite would have said so:
    here the poll worker never observes a task in flight, and the test fails on a bounded wait
    instead of hanging.

    A two-way handshake, not a pair of flags. The obvious version — the poll worker checking that
    the task "has not finished yet" — passes even when the planes ARE serialized: a task loop that
    ran first and gave up on its own timeout has still never been marked finished, so the check reads
    True with nothing overlapping. What must be recorded is the TASK's own observation that inference
    reached it while it was still inside its loop, because that is the only statement a serialized
    run cannot make.
    """
    from remote import serve, tasks

    monkeypatch.setenv("GRID_TASKS", "1")
    task_in_flight = threading.Event()
    inference_dispatched = threading.Event()
    recorded = threading.Event()
    overlapped: list[bool] = []

    def fake_task_loop(state):
        task_in_flight.set()
        # A task runs for minutes. Hold the plane open and see whether inference gets served here.
        overlapped.append(inference_dispatched.wait(5))
        recorded.set()
        state.tasks_stop.set()

    def poll(state):
        if task_in_flight.wait(5):
            inference_dispatched.set()
        state.stop.set()

    monkeypatch.setattr(tasks, "task_loop", fake_task_loop)
    monkeypatch.setattr(serve, "_poll_loop", poll)
    monkeypatch.setattr(serve, "_heartbeat_loop", lambda state: None)
    state = _serve_state(monkeypatch, tmp_path)

    serve._serve_loop(state)

    # `_serve_loop` deliberately does NOT join the task thread — a task runs for minutes and the
    # drain budget belongs to in-flight inference — so it can return before the observation above is
    # recorded. Without this wait the test passes or fails on scheduling luck.
    assert recorded.wait(5), "the task loop never finished recording what it saw"
    assert overlapped == [True], (
        "no inference was dispatched while the task loop was still running — the two planes are "
        "taking turns, not running side by side")


def test_serve_loop_drain_lets_inflight_job_finish(monkeypatch, tmp_path):
    """A job that finishes within the drain budget submits its result before _serve_loop returns —
    'drain', not 'kill on stop'."""
    from remote import serve

    submitted: list[str] = []

    def fake_poll(state):
        state.stop.set()          # shutdown begins while this 'job' is mid-flight
        # `enter_job`/`exit_job` is what the real `_poll_loop` brackets `handle_job` with, and what
        # the drain waits on. This fake replaces `_poll_loop` wholesale, so it has to declare the
        # job itself — a bare sleeping thread holds nothing the teardown could owe anyone.
        state.enter_job()
        try:
            time.sleep(0.05)          # in-flight work, well within _DRAIN_TIMEOUT
            submitted.append("done")  # result submitted before the worker returns
        finally:
            state.exit_job()

    monkeypatch.setattr(serve, "_poll_loop", fake_poll)
    monkeypatch.setattr(serve, "_heartbeat_loop", lambda state: None)
    state = _serve_state(monkeypatch, tmp_path, max_concurrency=1)

    serve._serve_loop(state)

    assert submitted == ["done"]


def test_serve_loop_drain_is_not_eaten_by_workers_parked_in_a_long_poll(monkeypatch, tmp_path):
    """The drain budget belongs to real work, not to idle threads.

    The sibling above passes with ONE worker, which is exactly why the starvation hid: joining
    workers in list order against a shared deadline means the FIRST parked poller — unwakeable, a
    long-poll runs to `relay.POLL_TIMEOUT` (35s) — consumes the whole budget, and every worker
    after it gets `join(timeout=0.0)`. Workers are idle almost always, so the busy one is almost
    never first. Here worker 1 parks and worker 2 holds a job: the job must still submit.
    """
    from remote import serve

    monkeypatch.setattr(serve, "_DRAIN_TIMEOUT", 1.0)
    parked = threading.Event()          # never set during drain → a real long-poll
    submitted: list[str] = []

    def fake_poll(state):
        if threading.current_thread().name == "poll-worker-1":   # joined FIRST today
            state.stop.set()            # shutdown begins
            parked.wait(30)
            return
        state.enter_job()               # poll-worker-2: genuinely holding a job
        try:
            time.sleep(0.1)             # work well inside _DRAIN_TIMEOUT
            submitted.append("done")
        finally:
            state.exit_job()

    monkeypatch.setattr(serve, "_poll_loop", fake_poll)
    monkeypatch.setattr(serve, "_heartbeat_loop", lambda state: None)
    state = _serve_state(monkeypatch, tmp_path, max_concurrency=2)

    try:
        serve._serve_loop(state)
    finally:
        parked.set()

    assert submitted == ["done"], "the parked worker ate the whole drain budget"
    assert state.jobs_held() == 0


def test_serve_loop_teardown_reports_jobs_not_idle_threads(monkeypatch, tmp_path, capsys):
    """Parked pollers hold no job, so abandoning them costs no consumer a response — saying they do
    sends an operator hunting a data-loss bug that isn't there (it did, once). Report the two
    separately: idle threads as an abandonment note, in-flight JOBS as the warning that matters."""
    from remote import serve

    monkeypatch.setattr(serve, "_DRAIN_TIMEOUT", 0.2)
    parked = threading.Event()

    def stuck_poll(state):
        state.stop.set()
        parked.wait(30)

    monkeypatch.setattr(serve, "_poll_loop", stuck_poll)
    monkeypatch.setattr(serve, "_heartbeat_loop", lambda state: None)
    state = _serve_state(monkeypatch, tmp_path, max_concurrency=4)

    try:
        serve._serve_loop(state)
    finally:
        parked.set()

    err = capsys.readouterr().err
    assert "4 poll worker(s) abandoned while parked" in err
    # No job was ever in flight, so the consumer-facing warning must NOT appear.
    assert "may see no terminal response" not in err


def test_relay_poll_malformed_body_raises_relay_error(monkeypatch):
    """A 200 with a non-JSON body is a transient relay fault → RelayError (retryable by _poll_loop),
    not a raw JSONDecodeError that would escape the loop's guards and kill the worker."""
